kNeighbours = input(7, "K Neighbours", 1, 15, 1)
lookbackBars = input(20, "Lookback Bars", 7, 60, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
marginThreshold = input(0.43, "Margin Threshold", 0.1, 0.9, 0.01)
agreementThreshold = input(0.65, "Agreement Threshold", 0.51, 0.95, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Model calculations ───────────────────────────────
ret = 0.0
if bar_index > 0 {
    ret := (close - close[1]) / (close[1] + 0.000000001)
}

varip retHist = array(0)
varip closeHist = array(0)

array.push(retHist, ret)
array.push(closeHist, close)

nHist = array.size(retHist)
warmup = bar_index > (lookbackBars + featureBars + 2)

upVotes = 0
downVotes = 0
voteMargin = 0.0
absMargin = 0.0
agreement = 0.0
disagreement = 1.0
minorFrac = 0.0

if warmup {
    kEff = kNeighbours
    if kEff < 1 { kEff := 1 }
    if kEff > 15 { kEff := 15 }

    bestDist = array()
    bestLab = array()
    ii = 0
    while ii < kEff {
        array.push(bestDist, 999999.0)
        array.push(bestLab, 0)
        ii := ii + 1
    }

    curEnd = nHist - 1
    L = 1
    while L <= lookbackBars {
        pEnd = curEnd - L
        pNext = pEnd + 1
        lab = 0 - 1
        if closeHist[pNext] > closeHist[pEnd] { lab := 1 }

        sumSq = 0.0
        f = 0
        while f < featureBars {
            a = retHist[curEnd - f] - retHist[pEnd - f]
            sumSq := sumSq + a * a
            f := f + 1
        }
        dist = sqrt(sumSq)

        insIdx = 0 - 1
        m = 0
        while m < kEff {
            if dist < bestDist[m] {
                insIdx := m
                m := kEff
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = kEff - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestLab, insIdx, lab)
        }
        L := L + 1
    }

    up = 0
    m = 0
    while m < kEff {
        if bestDist[m] < 999999.0 {
            if bestLab[m] == 1 { up := up + 1 }
        }
        m := m + 1
    }
    upVotes := up
    downVotes := kEff - up
    voteMargin := (upVotes - downVotes) / kEff
    absMargin := abs(voteMargin)
    if upVotes > downVotes { agreement := upVotes / kEff }
    if downVotes >= upVotes { agreement := downVotes / kEff }
    disagreement := 1.0 - absMargin
    if upVotes < downVotes { minorFrac := upVotes / kEff }
    if downVotes <= upVotes { minorFrac := downVotes / kEff }
}

bullState = warmup and absMargin > marginThreshold and agreement >= agreementThreshold and voteMargin > 0
bearState = warmup and absMargin > marginThreshold and agreement >= agreementThreshold and voteMargin < 0

buySig = bullState and not bullState[1] and warmup[1]
sellSig = bearState and not bearState[1] and warmup[1]

var lastDir = 0
if buySig { lastDir := 1 }
if sellSig { lastDir := 0 - 1 }

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

marginPct = voteMargin * 100 + close * 0.0
agreePct = agreement * 100 + close * 0.0
disagreePct = disagreement * 100 + close * 0.0

plot(marginPct, "Vote Margin", "#22cc88", 2, "separate")
plot(agreePct, "Agreement", "#ffd43b", 2, "separate")
plot(disagreePct, "Disagreement", "#ff4477", 1, "separate")

plot3d(marginPct, "Margin Pillars", "bars3d", "#22cc88", "separate")
plot3d(agreePct, "Agreement Plates", "scatter", "#ffd43b", "separate", 1)

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate")
}

ProfileRows = input(24, "ProfileRows", 5, 48, 1)
ValueAreaPercent = input(70, "ValueAreaPercent", 50, 90, 5)
SessionLengthBars = input(120, "SessionLengthBars", 30, 300, 10)
Show3DTerrain = input(true, "Show3DTerrain")
Show2DFallback = input(true, "Show2DFallback")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, SessionLengthBars)
ll = lowest(low, SessionLengthBars)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / ProfileRows

i = 0
k = 0
c = 0.0
b = 0
rv = 0.0
pocRow = 0
pocVol = 0 - 1.0
totalVol = 0.0
curRow = 0
volAtCloseRow = 0.0
vahP = 0.0
valP = 0.0
pocPrice = 0.0
target = 0.0

i := 0
pocVol := 0 - 1.0
totalVol := 0.0
pocRow := 0
while i < ProfileRows {
    rv := 0.0
    k := 0
    while k < SessionLengthBars {
        c := close[k]
        b := floor((c - ll) / rng * ProfileRows)
        if b < 0 {
            b := 0
        }
        if b > ProfileRows - 1 {
            b := ProfileRows - 1
        }
        if b == i {
            rv := rv + volume[k]
        }
        k := k + 1
    }
    totalVol := totalVol + rv
    if rv > pocVol {
        pocVol := rv
        pocRow := i
    }
    i := i + 1
}

pocPrice := ll + (pocRow + 0.5) * rowH

curRow := floor((close - ll) / rng * ProfileRows)
if curRow < 0 {
    curRow := 0
}
if curRow > ProfileRows - 1 {
    curRow := ProfileRows - 1
}
volAtCloseRow := 0.0
k := 0
while k < SessionLengthBars {
    c := close[k]
    b := floor((c - ll) / rng * ProfileRows)
    if b < 0 {
        b := 0
    }
    if b > ProfileRows - 1 {
        b := ProfileRows - 1
    }
    if b == curRow {
        volAtCloseRow := volAtCloseRow + volume[k]
    }
    k := k + 1
}

target := totalVol * ValueAreaPercent / 100
vaLowRow = pocRow
vaHighRow = pocRow
accum = pocVol
guard = 0
lowVol = 0.0
highVol = 0.0
lv = 0.0
hv = 0.0
while accum < target and guard < ProfileRows {
    lowVol := 0 - 1.0
    highVol := 0 - 1.0
    if vaLowRow > 0 {
        lv := 0.0
        k := 0
        while k < SessionLengthBars {
            c := close[k]
            b := floor((c - ll) / rng * ProfileRows)
            if b < 0 {
                b := 0
            }
            if b > ProfileRows - 1 {
                b := ProfileRows - 1
            }
            if b == vaLowRow - 1 {
                lv := lv + volume[k]
            }
            k := k + 1
        }
        lowVol := lv
    }
    if vaHighRow < ProfileRows - 1 {
        hv := 0.0
        k := 0
        while k < SessionLengthBars {
            c := close[k]
            b := floor((c - ll) / rng * ProfileRows)
            if b < 0 {
                b := 0
            }
            if b > ProfileRows - 1 {
                b := ProfileRows - 1
            }
            if b == vaHighRow + 1 {
                hv := hv + volume[k]
            }
            k := k + 1
        }
        highVol := hv
    }
    if highVol >= lowVol and vaHighRow < ProfileRows - 1 {
        vaHighRow := vaHighRow + 1
        accum := accum + highVol
    } else {
        if vaLowRow > 0 {
            vaLowRow := vaLowRow - 1
            accum := accum + lowVol
        } else {
            if vaHighRow < ProfileRows - 1 {
                vaHighRow := vaHighRow + 1
                accum := accum + highVol
            }
        }
    }
    guard := guard + 1
}
vahP := ll + (vaHighRow + 1) * rowH
valP := ll + vaLowRow * rowH

var lastPocLabelBar = 0.0

inside = close >= valP and close <= vahP
buyState = close > vahP
sellState = close < valP
buySig = buyState and inside[1]
sellSig = sellState and inside[1]
returnSig = inside and not inside[1]
pocLabelSig = (buySig or sellSig) and bar_index - lastPocLabelBar >= SessionLengthBars
if pocLabelSig {
    lastPocLabelBar := bar_index
}

if buySig {
    plotshape(bar_index, low, "LeaveUp", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "LeaveDn", "triangledown", "#ff4477")
}
if returnSig {
    plotshape(bar_index, close, "BackToValue", "circle", "#ffd43b")
}
if buySig {
    plotshape_3d(bar_index, low, "LeaveUp", "coneup", "#22cc88", markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "LeaveDn", "conedown", "#ff4477", markerSize, 1, "3d")
}
if pocLabelSig {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}

plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahP, "VAH", "#22cc88", 1, "stepline")
plot(valP, "VAL", "#ff4477", 1, "stepline")
plot(volAtCloseRow, "Row Volume At Price", "#4488ff", 1, "separate")

terrainCol = "#22cc88"
if not inside {
    terrainCol := "#ff8800"
}
plot3d(volAtCloseRow, "Value Terrain", "ridgeline", terrainCol, "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)

if not inside {
    bgcolor("rgba(255,136,0,0.05)")
}

flowBase = input(0, "Flow PSI Base", -50, 300, 1)
critical_threshold = input(150, "Critical Threshold", 50, 300, 1)
spin_factor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
ring_count = input(5, "Ring Count", 1, 5, 1)
