  r3 := perim
}
if r4 > maxR + 3.0 {
  r4 := perim
}
if r5 > maxR + 4.0 {
  r5 := perim
}
if locked_state == false {
  r1 := perim
  r2 := perim
  r3 := perim
  r4 := perim
  r5 := perim
